style.css:
/* Gemini AI chat content area widening */
/* Target main conversation container */
main[class*="main"],
div[class*="conversation"][class*="container"],
div[data-test-id*="conversation"] {
    max-width: 90vw !important;
    width: 100% !important;
}

/* Target response containers */
div[class*="model-response"],
div[class*="response-container"] {
    max-width: none !important;
}

/* Remove prose width limits */
div[class*="prose"],
article[class*="response"] {
    max-width: none !important;
}
